 21→// Cursor hook names - these become subcommands under `entire hooks cursor`
 22→const (
 23→	HookNameSessionStart       = "session-start"
 24→	HookNameSessionEnd         = "session-end"
 25→	HookNameBeforeSubmitPrompt = "before-submit-prompt"
 26→	HookNameStop               = "stop"
 27→	HookNamePreTask            = "pre-task"
 28→	HookNamePostTask           = "post-task"
 29→	HookNamePostTodo           = "post-todo"
 30→)
 31→
 32→// HooksFileName is the hooks file used by Cursor.
 33→const HooksFileName = "hooks.json"
 34→
 35→// entireHookPrefixes are command prefixes that identify Entire hooks
 36→var entireHookPrefixes = []string{
 37→	"entire ",
 38→	"go run ${CURSOR_PROJECT_DIR}/cmd/entire/main.go ",
 39→}
