 55→// InstallHooks installs Cursor hooks in .cursor/hooks.json.
 56→// If force is true, removes existing Entire hooks before installing.
 57→// Returns the number of hooks installed.
 58→func (c *CursorAgent) InstallHooks(localDev bool, force bool) (int, error) {
 59→	repoRoot, err := paths.RepoRoot()
 60→	if err != nil {
 61→		repoRoot, err = os.Getwd() //nolint:forbidigo // Intentional fallback when RepoRoot() fails (tests run outside git repos)
 62→		if err != nil {
 63→			return 0, fmt.Errorf("failed to get current directory: %w", err)
 64→		}
 65→	}
 66→
 67→	hooksPath := filepath.Join(repoRoot, ".cursor", HooksFileName)
 68→
 69→	// Read existing hooks file if it exists
 70→	var hooksFile CursorHooksFile
 71→
 72→	existingData, readErr := os.ReadFile(hooksPath) //nolint:gosec // path is constructed from repo root + fixed path
 73→	if readErr == nil {
 74→		if err := json.Unmarshal(existingData, &hooksFile); err != nil {
 75→			return 0, fmt.Errorf("failed to parse existing "+HooksFileName+": %w", err)
 76→		}
 77→	} else {
 78→		hooksFile.Version = 1
 79→	}
 80→
 81→	// If force is true, remove all existing Entire hooks first
 82→	if force {
 83→		hooksFile.Hooks.SessionStart = removeEntireHooks(hooksFile.Hooks.SessionStart)
 84→		hooksFile.Hooks.SessionEnd = removeEntireHooks(hooksFile.Hooks.SessionEnd)
 85→		hooksFile.Hooks.BeforeSubmitPrompt = removeEntireHooks(hooksFile.Hooks.BeforeSubmitPrompt)
 86→		hooksFile.Hooks.Stop = removeEntireHooks(hooksFile.Hooks.Stop)
 87→		hooksFile.Hooks.PreToolUse = removeEntireHooks(hooksFile.Hooks.PreToolUse)
 88→		hooksFile.Hooks.PostToolUse = removeEntireHooks(hooksFile.Hooks.PostToolUse)
 89→	}
 90→
 91→	// Define hook commands
 92→	var cmdPrefix string
 93→	if localDev {
 94→		cmdPrefix = "go run ${CURSOR_PROJECT_DIR}/cmd/entire/main.go hooks cursor "
 95→	} else {
 96→		cmdPrefix = "entire hooks cursor "
 97→	}
 98→
 99→	sessionStartCmd := cmdPrefix + "session-start"
100→	sessionEndCmd := cmdPrefix + "session-end"
101→	beforeSubmitPromptCmd := cmdPrefix + "before-submit-prompt"
102→	stopCmd := cmdPrefix + "stop"
103→	preTaskCmd := cmdPrefix + "pre-task"
104→	postTaskCmd := cmdPrefix + "post-task"
105→	postTodoCmd := cmdPrefix + "post-todo"
106→
107→	count := 0
108→
109→	// Add hooks if they don't exist
110→	if !hookCommandExists(hooksFile.Hooks.SessionStart, sessionStartCmd) {
111→		hooksFile.Hooks.SessionStart = append(hooksFile.Hooks.SessionStart, CursorHookEntry{Command: sessionStartCmd})
112→		count++
113→	}
114→	if !hookCommandExists(hooksFile.Hooks.SessionEnd, sessionEndCmd) {
115→		hooksFile.Hooks.SessionEnd = append(hooksFile.Hooks.SessionEnd, CursorHookEntry{Command: sessionEndCmd})
116→		count++
117→	}
118→	if !hookCommandExists(hooksFile.Hooks.BeforeSubmitPrompt, beforeSubmitPromptCmd) {
119→		hooksFile.Hooks.BeforeSubmitPrompt = append(hooksFile.Hooks.BeforeSubmitPrompt, CursorHookEntry{Command: beforeSubmitPromptCmd})
120→		count++
121→	}
122→	if !hookCommandExists(hooksFile.Hooks.Stop, stopCmd) {
123→		hooksFile.Hooks.Stop = append(hooksFile.Hooks.Stop, CursorHookEntry{Command: stopCmd})
124→		count++
125→	}
126→	if !hookCommandExistsWithMatcher(hooksFile.Hooks.PreToolUse, "Task", preTaskCmd) {
127→		hooksFile.Hooks.PreToolUse = append(hooksFile.Hooks.PreToolUse, CursorHookEntry{Command: preTaskCmd, Matcher: "Task"})
128→		count++
129→	}
130→	if !hookCommandExistsWithMatcher(hooksFile.Hooks.PostToolUse, "Task", postTaskCmd) {
131→		hooksFile.Hooks.PostToolUse = append(hooksFile.Hooks.PostToolUse, CursorHookEntry{Command: postTaskCmd, Matcher: "Task"})
132→		count++
133→	}
134→	if !hookCommandExistsWithMatcher(hooksFile.Hooks.PostToolUse, "TodoWrite", postTodoCmd) {
135→		hooksFile.Hooks.PostToolUse = append(hooksFile.Hooks.PostToolUse, CursorHookEntry{Command: postTodoCmd, Matcher: "TodoWrite"})
136→		count++
137→	}
138→
139→	if count == 0 {
140→		return 0, nil
141→	}
142→
143→	// Write to file
144→	if err := os.MkdirAll(filepath.Dir(hooksPath), 0o750); err != nil {
145→		return 0, fmt.Errorf("failed to create .cursor directory: %w", err)
146→	}
147→
148→	output, err := jsonutil.MarshalIndentWithNewline(hooksFile, "", "  ")
149→	if err != nil {
150→		return 0, fmt.Errorf("failed to marshal "+HooksFileName+": %w", err)
151→	}
152→
153→	if err := os.WriteFile(hooksPath, output, 0o600); err != nil {
154→		return 0, fmt.Errorf("failed to write "+HooksFileName+": %w", err)
155→	}
156→
157→	return count, nil
158→}
