197→// AreHooksInstalled checks if Entire hooks are installed.
198→func (c *CursorAgent) AreHooksInstalled() bool {
199→	repoRoot, err := paths.RepoRoot()
200→	if err != nil {
201→		repoRoot = "."
202→	}
203→	hooksPath := filepath.Join(repoRoot, ".cursor", HooksFileName)
204→	data, err := os.ReadFile(hooksPath) //nolint:gosec // path is constructed from repo root + fixed path
205→	if err != nil {
206→		return false
207→	}
208→
209→	var hooksFile CursorHooksFile
210→	if err := json.Unmarshal(data, &hooksFile); err != nil {
211→		return false
212→	}
213→
214→	return hasEntireHook(hooksFile.Hooks.SessionStart) ||
215→		hasEntireHook(hooksFile.Hooks.SessionEnd) ||
216→		hasEntireHook(hooksFile.Hooks.BeforeSubmitPrompt) ||
217→		hasEntireHook(hooksFile.Hooks.Stop) ||
218→		hasEntireHook(hooksFile.Hooks.PreToolUse) ||
219→		hasEntireHook(hooksFile.Hooks.PostToolUse)
220→}
