224→	return []agent.HookType{
225→		agent.HookSessionStart,
226→		agent.HookSessionEnd,
227→		agent.HookUserPromptSubmit,
228→		agent.HookStop,
229→		agent.HookPreToolUse,
230→		agent.HookPostToolUse,
231→	}
232→}
