188→func TestInstallHooks_PreservesExistingHooks(t *testing.T) {
189→	tempDir := t.TempDir()
190→	t.Chdir(tempDir)
191→
192→	// Create hooks file with existing user hooks
193→	writeHooksFile(t, tempDir, CursorHooksFile{
194→		Version: 1,
195→		Hooks: CursorHooks{
196→			Stop: []CursorHookEntry{
197→				{Command: "echo user hook"},
198→			},
199→			PostToolUse: []CursorHookEntry{
200→				{Command: "echo file written", Matcher: "Write"},
201→			},
202→		},
203→	})
204→
205→	ag := &CursorAgent{}
206→	_, err := ag.InstallHooks(false, false)
207→	if err != nil {
208→		t.Fatalf("InstallHooks() error = %v", err)
209→	}
210→
211→	hooksFile := readHooksFile(t, tempDir)
212→
213→	// Stop should have user hook + entire hook
