223→	}
224→	assertEntryWithMatcher(t, hooksFile.Hooks.PostToolUse, "Write", "echo file written")
225→	assertEntryWithMatcher(t, hooksFile.Hooks.PostToolUse, "Task", "entire hooks cursor post-task")
226→	assertEntryWithMatcher(t, hooksFile.Hooks.PostToolUse, "TodoWrite", "entire hooks cursor post-todo")
227→}
